def length_of_lis(nums: list[int]) -> int:
    # tails[L] = smallest tail of any increasing subsequence of length L + 1.
    tails = []
    for x in nums:
        pos = bisect.bisect_left(tails, x)  # first tail >= x
        if pos == len(tails):
            tails.append(x)    # x extends the longest subsequence
        else:
            tails[pos] = x     # x is a better (smaller) tail for length pos + 1
    return len(tails)

