def combination_sum(candidates: list[int], target: int) -> list[list[int]]:
    nums = sorted(candidates)
    results = []
    path = []

    def search(start: int, remaining: int) -> None:
        if remaining == 0:
            results.append(path[:])
            return
        for j in range(start, len(nums)):
            if nums[j] > remaining:
                break                         # sorted, so later ones are larger too
            path.append(nums[j])
            search(j, remaining - nums[j])    # j, not j + 1: reuse is allowed
            path.pop()

    search(0, target)
    return results

