def calc_equation(equations: list[list[str]], values: list[float],
                  queries: list[list[str]]) -> list[float]:
    parent = {}
    ratio = {}       # ratio[x] = x / parent[x]

    def find(x):
        # Collect the path to the root, then point every node at the root.
        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        root = x
        for node in reversed(path):           # nodes nearest the root first
            ratio[node] *= ratio[parent[node]]
            parent[node] = root
        return root

    for (a, b), v in zip(equations, values):
        for x in (a, b):
            if x not in parent:
                parent[x] = x
                ratio[x] = 1.0
        ra, rb = find(a), find(b)
        if ra != rb:
            # a = ratio[a] * ra and b = ratio[b] * rb, with a / b = v.
            parent[ra] = rb
            ratio[ra] = v * ratio[b] / ratio[a]

    answers = []
    for c, d in queries:
        if c not in parent or d not in parent or find(c) != find(d):
            answers.append(-1.0)
        else:
            answers.append(ratio[c] / ratio[d])
    return answers

