def lowest_common_ancestor(root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:
    parent = {root: None}
    stack = [root]
    # Record parent links until both targets have been reached.
    while p not in parent or q not in parent:
        node = stack.pop()
        for child in (node.left, node.right):
            if child:
                parent[child] = node
                stack.append(child)
    # Every ancestor of p, including p itself.
    ancestors = set()
    node = p
    while node:
        ancestors.add(node)
        node = parent[node]
    # Climb from q until the two paths meet.
    node = q
    while node not in ancestors:
        node = parent[node]
    return node

