    stack = [-1]   # bottom: index just before the current valid stretch
    best = 0
    for i, ch in enumerate(s):
        if ch == "(":
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)           # unmatched ')' becomes the new boundary
            else:
                best = max(best, i - stack[-1])
    return best

def jump(nums: list[int]) -> int:
    jumps = 0
    current_end = 0   # last index reachable with `jumps` jumps
    farthest = 0      # farthest index reachable with one more jump
    for i in range(len(nums) - 1):
        farthest = max(farthest, i + nums[i])
        if i == current_end:
            jumps += 1
            current_end = farthest
    return jumps

def least_interval(tasks: list[str], n: int) -> int:
    ready = [-c for c in Counter(tasks).values()]   # max heap of remaining counts
    heapq.heapify(ready)
    cooling = deque()       # (time the label is ready again, negated remaining count)
    time = 0
    while ready or cooling:
        if not ready:
            time = max(time, cooling[0][0])          # nothing runnable: skip idle units
        while cooling and cooling[0][0] <= time:
            heapq.heappush(ready, cooling.popleft()[1])
        remaining = heapq.heappop(ready) + 1         # run one copy of the busiest label
        time += 1
        if remaining:
            cooling.append((time + n, remaining))
    return time

