def number_to_words(num: int) -> str:
    if num == 0:
        return "Zero"

    def group_words(n: int) -> list[str]:
        # Words for 1 <= n <= 999.
        words = []
        if n >= 100:
            words += [BELOW_20[n // 100], "Hundred"]
            n %= 100
        if n >= 20:
            words.append(TENS[n // 10])
            n %= 10
        if n:
            words.append(BELOW_20[n])
        return words

    words = []
    for value, name in SCALES:
        group, num = divmod(num, value)
        if group:
            words += group_words(group)
            if name:
                words.append(name)
    return " ".join(words)

