def remove_kdigits(num: str, k: int) -> str:
    stack = []
    for digit in num:
        # A larger digit in front of a smaller one should go.
        while k and stack and stack[-1] > digit:
            stack.pop()
            k -= 1
        stack.append(digit)
    if k:
        stack = stack[:-k]       # remaining digits are non decreasing
    result = "".join(stack).lstrip("0")
    return result or "0"

