def alien_order(words: list[str]) -> str:
    letters = set("".join(words))
    after = {ch: set() for ch in letters}       # edges: ch comes before each letter in after[ch]
    for first, second in zip(words, words[1:]):
        for a, b in zip(first, second):
            if a != b:
                after[a].add(b)
                break
        else:
            # No differing position: the longer word must not come first.
            if len(first) > len(second):
                return ""

    indegree = {ch: 0 for ch in letters}
    for ch in letters:
        for nxt in after[ch]:
            indegree[nxt] += 1
    ready = deque(ch for ch in letters if indegree[ch] == 0)
    order = []
    while ready:
        ch = ready.popleft()
        order.append(ch)
        for nxt in after[ch]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                ready.append(nxt)
    return "".join(order) if len(order) == len(letters) else ""

