def split_array(nums: list[int], k: int) -> int:
    def pieces_needed(cap: int) -> int:
        pieces, current = 1, 0
        for x in nums:
            if current + x > cap:
                pieces += 1      # start a new piece with x
                current = x
            else:
                current += x
        return pieces

