class MyCircularQueue:
    def __init__(self, k: int):
        self.slots = [0] * k
        self.head = 0       # index of the front item
        self.count = 0      # number of stored items

    def enQueue(self, value: int) -> bool:
        if self.isFull():
            return False
        self.slots[(self.head + self.count) % len(self.slots)] = value
        self.count += 1
        return True

    def deQueue(self) -> bool:
        if self.isEmpty():
            return False
        self.head = (self.head + 1) % len(self.slots)
        self.count -= 1
        return True

    def Front(self) -> int:
        return -1 if self.isEmpty() else self.slots[self.head]

    def Rear(self) -> int:
        if self.isEmpty():
            return -1
        return self.slots[(self.head + self.count - 1) % len(self.slots)]

    def isEmpty(self) -> bool:
        return self.count == 0

    def isFull(self) -> bool:
        return self.count == len(self.slots)

