def is_match(s: str, p: str) -> bool:
    i = j = 0
    star = -1        # index of the most recent '*' in p
    mark = 0         # position in s where that star's match currently ends
    while i < len(s):
        if j < len(p) and (p[j] == "?" or p[j] == s[i]):
            i += 1
            j += 1
        elif j < len(p) and p[j] == "*":
            star, mark = j, i        # let the star match nothing for now
            j += 1
        elif star != -1:
            mark += 1                # the star swallows one more character
            i, j = mark, star + 1
        else:
            return False
    while j < len(p) and p[j] == "*":
        j += 1
    return j == len(p)

def word_break(s: str, wordDict: list[str]) -> list[str]:
    # Trie of the dictionary; "$" marks a word end.
    root = {}
    for w in wordDict:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = True

    n = len(s)
    ways = [[] for _ in range(n + 1)]   # ways[i]: sentences for s[i:]
    ways[n] = [""]
    for i in range(n - 1, -1, -1):
        node = root
        for j in range(i, n):
            node = node.get(s[j])
            if node is None:
                break
            if "$" in node and ways[j + 1]:
                word = s[i:j + 1]
                for rest in ways[j + 1]:
                    ways[i].append(word + " " + rest if rest else word)
    return ways[0]
